  function trackingCards(list,editable){return `<section class="tracking-manager"><div class="tracking-manager-head"><div><p class="eyebrow">${es('SEGUIMIENTO DE COMPRA','PURCHASE TRACKING')}</p><h2>${es('Tracking de órdenes','Order tracking')}</h2></div></div><div class="tracking-list">${list.length?list.map(order=>{let index=currentView.state.orders.findIndex(x=>x.id===order.id),editor=order.trackingUpdatedBy;return `<article class="tracking-card" data-tracking-search="${trackingNumber(order,index).toLowerCase()}"><div><strong>${trackingNumber(order,index)}</strong><small>${escape(order.number)} · ${escape(order.supplier)}</small></div><div class="tracking-status-group"><span class="tracking-status"><b>${es('Estado:','Status:')}</b> ${trackingLabel(order.trackingStatus)}</span>${editable?`<button class="secondary tracking-update-btn" data-edit-tracking="${order.id}" aria-label="${es('Actualizar estado de tracking','Update tracking status')}">${icon('edit')} ${es('Actualizar estado','Update status')}</button>`:''}</div><small>${es('Último en editar:','Last edited by:')} ${escape(editor?.username||'—')}${editor?.name?` · ${escape(editor.name)}`:''}</small>${editable?`<div class="tracking-actions"><button class="secondary tracking-action-btn" data-preview-tracking="${order.id}" aria-label="${es('Ver orden','View order')}">${icon('eye')} ${es('Ver','View')}</button><button class="secondary tracking-action-btn" data-download-tracking="${order.id}" aria-label="${es('Descargar orden','Download order')}">↓ ${es('Descargar','Download')}</button><button class="danger tracking-action-btn" data-delete-project-order="${order.id}" aria-label="${es('Eliminar orden','Delete order')}">${icon('trash')} ${es('Eliminar','Delete')}</button></div>`:''}</article>`}).join(''):`<p class="empty">${es('Aún no hay órdenes para seguir.','There are no orders to track yet.')}</p>`}</div></section>`}
  function enhanceTracking(){if(!currentView?.state)return;let state=currentView.state,project=state.projects.find(p=>p.id===currentView.selectedProjectId),route=currentView.route;if(route==='project'&&project){let host=document.querySelector('.project-purchase-section');if(host&&!host.querySelector('.tracking-manager'))host.insertAdjacentHTML('beforeend',trackingCards(state.orders.filter(o=>o.projectId===project.id),['Admin','Worker'].includes(currentView.user.role)))}if(route==='orders'&&currentView.user.role==='Client'){let host=document.querySelector('.order-history-page');if(host&&!host.querySelector('.client-tracking-search')){host.insertAdjacentHTML('afterbegin',`<label class="client-tracking-search">${icon('search')}<input id="client-tracking-search" placeholder="${es('Buscar por número de tracking','Search by tracking number')}"></label>`);let table=host.querySelector('.user-table-wrap');if(table)table.insertAdjacentHTML('beforebegin',trackingCards(ACL.selectOrdersForActor(state,currentView.user),false))}}}
