  function invoiceContactOptions(project){let defaults=[{name:'María Fernanda López',role:'Gerente de Proyecto',phone:'+51 987 123 456'},{name:'Jorge Ramírez',role:'Administrador de Obra',phone:'+51 956 321 780'},{name:'Lucía Torres',role:'Coordinadora de Compras',phone:'+51 944 876 210'}],contacts=[...(project.team?.length?project.team:defaults),...currentView.state.users.filter(user=>user.active).map(user=>({name:user.name,role:user.role,phone:user.phone||user.email})),...currentView.state.suppliers.filter(supplier=>supplier.active).map(supplier=>({name:supplier.contactName||supplier.contact||supplier.name,role:supplier.name,phone:supplier.phone||supplier.email}))],unique=[...new Map(contacts.filter(contact=>contact.name).map(contact=>[contact.name,contact])).values()];return `<datalist id="invoice-contacts">${unique.map(contact=>`<option value="${escape(contact.name)}">${escape([contact.role,contact.phone].filter(Boolean).join(' · '))}</option>`).join('')}</datalist>`}
  function moneyField(label,name,required=false){return `<label class="field">${label}<div class="money-input"><select name="${name}Currency"><option value="PEN">PEN</option><option value="USD">USD</option><option value="EUR">EUR</option><option value="COP">COP</option></select><input name="${name}" type="number" min="0" step=".01" ${required?'required':''}></div></label>`}
  function showInvoiceEditor(descriptor){activeOperation=descriptor;let project=descriptor.target,orders=currentView.state.orders.filter(order=>order.projectId===project.id);modal.innerHTML=`<div class="modal-backdrop"><form class="modal invoice-modal" id="invoice-editor-form"><header class="modal-head"><h2>${es('Generar nueva factura','Generate new invoice')}</h2><button type="button" class="ghost" data-command="close">✕</button></header><div class="modal-body">${invoiceContactOptions(project)}<p class="po-form-intro">${es('Completa únicamente los campos del formato Payment Request. El código de solicitud se genera automáticamente.','Complete only the Payment Request fields. The request code is generated automatically.')}</p><h3>${es('Solicitud','Request')}</h3><div class="po-form-grid"><label class="field">${es('N° de OC','PO #')}<select name="poNumber" required><option value="">${es('Seleccionar orden de compra','Select purchase order')}</option>${orders.map(order=>`<option value="${escape(order.number)}">${escape(order.number)} · ${escape(order.supplier)}</option>`).join('')}</select></label>${invoiceField(es('Fecha de solicitud','Request date'),'requestDate','date')}<label class="field full">${es('Detalle de la solicitud','Request detail')}<textarea name="requestDetail" required></textarea></label>${moneyField(es('Total de la solicitud','Total for this request'),'totalRequest',true)}</div><h3>${es('Partes','Parties')}</h3><div class="po-form-grid">${invoiceField(es('Fuente / fabricante','Source / manufacturer'),'sourceManufacturer')} ${invoiceField(es('Pagadero a','Payable to'),'payableTo')} ${invoiceField(es('Dirección de pago','Payment address'),'payableAddress')}<label class="field">${es('Contacto','Contact')}<input name="payableContact" list="invoice-contacts" placeholder="${es('Selecciona o escribe para buscar','Select or type to search')}" required></label></div><h3>${es('Detalle de factura','Invoice entry details')}</h3><div class="po-form-grid">${invoiceField(es('Código de factura','Invoice #'),'invoiceNumber')} ${invoiceField(es('Referencia OC / área','PO ref # (area)'),'poReferenceArea')} ${invoiceField(es('Fecha de factura','Invoice date'),'invoiceDate','date')} ${invoiceField(es('Fecha de vencimiento','Due date'),'dueDate','date')} ${invoiceField(es('Términos de pago','Payment terms'),'paymentTerms')}</div><h3>${es('Desglose de montos','Amount breakdown')}</h3><div class="invoice-breakdown">${moneyField(es('Mercadería','Goods'),'goods')}${moneyField(es('Flete','Freight'),'freight')}${moneyField(es('Embalaje','Packing'),'packing')}${moneyField(es('Cargos adicionales','Add’l charges'),'additionalCharges')}${moneyField(es('Sobrecosto','Overage'),'overage')}${moneyField(es('Aduanas','Customs'),'customs')}${moneyField(es('Impuesto a las ventas','Sales tax'),'salesTax')}</div></div><footer class="modal-foot"><button type="button" class="secondary" data-command="close">${es('Cancelar','Cancel')}</button><button class="primary">${es('Generar factura','Generate invoice')}</button></footer></form></div>`;let form=modal.querySelector('#invoice-editor-form');form.dataset.operationToken=descriptor.operationToken;form.dataset.projectId=project.id}
  function paymentRequestPreview(project,invoice){let value=name=>escape(invoice[name]||'—'),formatted=name=>{let amount=Number(invoice[name]||0);return amount?escape(new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(amount)):'—'},money=(name,currency='currency')=>`${value(currency)} ${formatted(name)}`;return `<div class="payment-request-preview"><img src="assets/payment-request-template.png" alt="Formato de solicitud de pago HPG"><span class="pr-fill pr-number">${value('number')}</span><span class="pr-fill pr-project">${escape(project.name)}</span><span class="pr-fill pr-po">${value('poNumber')}</span><span class="pr-fill pr-date">${value('requestDate')}</span><span class="pr-fill pr-currency">${value('currency')}</span><span class="pr-fill pr-detail">${value('requestDetail')}</span><span class="pr-fill pr-total-request">${money('totalRequest')}</span><span class="pr-fill pr-source">${value('sourceManufacturer')}</span><span class="pr-fill pr-payable">${value('payableTo')}</span><span class="pr-fill pr-payable-address">${value('payableAddress')}</span><span class="pr-fill pr-payable-contact">${es('Contacto: ','Contact: ')}${value('payableContact')}</span><span class="pr-fill pr-invoice">${value('invoiceNumber')}</span><span class="pr-fill pr-po-ref">${value('poReferenceArea')}</span><span class="pr-fill pr-invoice-date">${value('invoiceDate')}</span><span class="pr-fill pr-due-date">${value('dueDate')}</span><span class="pr-fill pr-terms">${value('paymentTerms')}</span><span class="pr-fill pr-invoice-payable">${value('payableTo')}</span><span class="pr-fill pr-invoice-currency">${value('currency')}</span><span class="pr-fill pr-invoice-total">${money('totalRequest')}</span>${['totalRequest','goods','freight','packing','additionalCharges','overage','customs','salesTax'].map((name,index)=>`<span class="pr-fill pr-breakdown-${index}">${formatted(name)}</span>`).join('')}<span class="pr-fill pr-payment-to">${value('payableTo')}</span><span class="pr-fill pr-payment-amount">${money('totalRequest')}</span><span class="pr-fill pr-requested">${value('requestedBy')}</span></div>`}
  function showInvoicePreview(descriptor){activeOperation=null;let invoice=descriptor.invoice;if(!invoice)return;modal.innerHTML=`<div class="modal-backdrop"><section class="modal invoice-preview-modal"><header class="modal-head"><h2>${es('Previsualización de factura','Invoice preview')}</h2><button type="button" class="ghost" data-command="close">✕</button></header><div class="modal-body">${paymentRequestPreview(descriptor.target,invoice)}</div><footer class="modal-foot"><button type="button" class="secondary" data-command="close">${es('Cerrar','Close')}</button><button class="primary" data-print-invoice>${es('Descargar PDF','Download PDF')}</button></footer></section></div>`}
  document.addEventListener('click',event=>{let create=event.target.closest('[data-new-invoice]');if(create){event.preventDefault();event.stopImmediatePropagation();let id=create.dataset.newInvoice,result=runtime.dispatchAction({action:'new-invoice',phase:'open',targetId:id,resource:{type:'project',id}});if(result.ok)showInvoiceEditor(result.descriptor);return}let preview=event.target.closest('[data-preview-invoice]');if(preview){event.preventDefault();event.stopImmediatePropagation();let id=preview.dataset.projectId,result=runtime.dispatchAction({action:'preview-invoice',phase:'open',targetId:id,resource:{type:'project',id},payload:{invoiceId:preview.dataset.previewInvoice}});if(result.ok)showInvoicePreview(result.descriptor);return}if(event.target.closest('[data-print-invoice]')){event.preventDefault();document.body.classList.add('print-invoice');window.print();setTimeout(()=>document.body.classList.remove('print-invoice'),500)}},true);
  document.addEventListener('submit',event=>{let form=event.target;if(form.id!=='invoice-editor-form')return;event.preventDefault();event.stopImmediatePropagation();let id=form.dataset.projectId,raw=Object.fromEntries(new FormData(form).entries()),currency=raw.totalRequestCurrency||'PEN',payload={...raw,currency,invoiceCurrency:currency,invoiceTotal:raw.totalRequest,paymentAmount:raw.totalRequest,paymentPayableTo:raw.payableTo,requestedBy:'HPG International Latinoamericana SAC'},result=runtime.dispatchAction({action:'new-invoice',phase:'commit',targetId:id,resource:{type:'project',id},operationToken:form.dataset.operationToken,payload});if(result.ok){activeOperation=null;modal.innerHTML='';renderCurrentRoute();message(es('Factura generada.','Invoice generated.'))}else message(ACL.t(lang(),'stale'))},true);
  function showProjectDocumentDeletion(descriptor,kind){activeOperation=descriptor;let invoice=descriptor.invoice,target=kind==='invoice'?invoice:descriptor.target,label=kind==='invoice'?es('factura','invoice'):es('orden de compra','purchase order'),reference=kind==='invoice'?invoice?.number:target?.number;modal.innerHTML=`<div class="modal-backdrop"><form class="modal" id="project-document-delete-form" data-kind="${kind}"><header class="modal-head"><h2>${es('Confirmar eliminación','Confirm deletion')}</h2><button type="button" class="ghost" data-command="close">✕</button></header><div class="modal-body"><p class="confirm-question">${es(`¿Estás seguro que deseas eliminar esta ${label}?`,`Are you sure you want to delete this ${label}?`)}</p><p><strong>${escape(reference||'')}</strong></p></div><footer class="modal-foot"><button type="button" class="secondary" data-command="close">${es('No, volver','No, go back')}</button><button class="danger">${es('Sí, eliminar','Yes, delete')}</button></footer></form></div>`}
  document.addEventListener('click',event=>{let orderButton=event.target.closest('[data-delete-project-order]');if(orderButton){event.preventDefault();event.stopImmediatePropagation();let id=orderButton.dataset.deleteProjectOrder,result=runtime.dispatchAction({action:'delete-order',phase:'open',targetId:id,resource:{type:'order',id}});if(result.ok)showProjectDocumentDeletion(result.descriptor,'order');else message(ACL.t(lang(),'denied'));return}let invoiceButton=event.target.closest('[data-delete-invoice]');if(!invoiceButton)return;event.preventDefault();event.stopImmediatePropagation();let id=invoiceButton.dataset.projectId,result=runtime.dispatchAction({action:'delete-invoice',phase:'open',targetId:id,resource:{type:'project',id},payload:{invoiceId:invoiceButton.dataset.deleteInvoice}});if(result.ok)showProjectDocumentDeletion(result.descriptor,'invoice');else message(ACL.t(lang(),'denied'))},true);
  document.addEventListener('submit',event=>{let form=event.target;if(form.id!=='project-document-delete-form')return;event.preventDefault();event.stopImmediatePropagation();let kind=form.dataset.kind,action=kind==='invoice'?'delete-invoice':'delete-order',targetId=kind==='invoice'?activeOperation?.target?.id:activeOperation?.target?.id,resource={type:kind==='invoice'?'project':'order',id:targetId},payload=kind==='invoice'?{invoiceId:activeOperation?.invoice?.id}:{},result=runtime.dispatchAction({action,phase:'commit',targetId,resource,operationToken:activeOperation?.operationToken,payload});if(result.ok){activeOperation=null;modal.innerHTML='';renderCurrentRoute();message(es(kind==='invoice'?'Factura eliminada.':'Orden de compra eliminada.',kind==='invoice'?'Invoice deleted.':'Purchase order deleted.'))}else message(ACL.t(lang(),'stale'))},true);
  function reportsSection(){if(currentView?.route!=='project'||!['Admin','Worker'].includes(currentView.user.role))return;let project=currentView.state.projects.find(item=>item.id===currentView.selectedProjectId),invoiceHost=document.querySelector('.project-invoice-section'),purchaseHost=document.querySelector('.project-purchase-section'),host=invoiceHost||purchaseHost;if(!project||!host||host.parentElement.querySelector('.project-reports-section'))return;let orderCount=currentView.state.orders.filter(order=>order.projectId===project.id).length,invoiceCount=(project.invoices||[]).length;host.insertAdjacentHTML('afterend',`<section class="section project-reports-section"><div class="section-head"><div><p class="eyebrow">${es('CONTROL Y EXPORTACIÓN','CONTROL AND EXPORT')}</p><h2>${es('Reportes','Reports')}</h2><p>${es('Descarga los reportes Excel del proyecto actual.','Download Excel reports for the current project.')}</p></div></div><div class="project-report-list"><article class="project-report-card"><div class="report-card-icon">↓</div><div><h3>${es('Reporte de órdenes de compra','Purchase order report')}</h3><p>${es('Ítems, costos, estados y seguimiento de las órdenes del proyecto.','Items, costs, statuses and tracking for project orders.')}</p><small>${orderCount} ${es('órdenes registradas','orders registered')}</small></div><button class="secondary" data-project-report="orders" data-project-id="${project.id}">↓ ${es('Descargar Excel','Download Excel')}</button></article><article class="project-report-card"><div class="report-card-icon">▤</div><div><h3>${es('Reporte de facturas','Invoice report')}</h3><p>${es('Solicitudes de pago, importes y detalles de facturación del proyecto.','Payment requests, amounts and invoicing details for the project.')}</p><small>${invoiceCount} ${es('facturas registradas','invoices registered')}</small></div><button class="secondary" data-project-report="invoices" data-project-id="${project.id}">↓ ${es('Descargar Excel','Download Excel')}</button></article></div></section>`)}new MutationObserver(reportsSection).observe(app,{childList:true,subtree:true});reportsSection();
  document.addEventListener('click',event=>{let button=event.target.closest('[data-project-report]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();let project=currentView?.state.projects.find(item=>item.id===button.dataset.projectId);if(!project||!window.VAAKReports)return message(es('No se pudo generar el reporte.','The report could not be generated.'));if(button.dataset.projectReport==='orders')window.VAAKReports.purchaseOrders(project,currentView.state.orders);else window.VAAKReports.invoices(project,currentView.state.orders);message(es('Reporte Excel descargado.','Excel report downloaded.'))},true);
  function showHistoryOrderDeletion(descriptor){activeOperation=descriptor;let order=descriptor.target;modal.innerHTML=`<div class="modal-backdrop"><form class="modal confirm-delete-order" id="history-order-delete-form"><header class="modal-head"><h2>${es('Eliminar orden de compra','Delete purchase order')}</h2><button type="button" class="ghost" data-command="close">✕</button></header><div class="modal-body"><p class="confirm-question">${es('¿ESTÁS SEGURO DE QUE DESEAS ELIMINAR ESTA ORDEN DE COMPRA?','ARE YOU SURE YOU WANT TO DELETE THIS PURCHASE ORDER?')}</p><p><strong>${escape(order?.number||'')}</strong> · ${escape(order?.supplier||'')}</p></div><footer class="modal-foot"><button type="button" class="secondary" data-command="close">${es('No, mantener la orden','No, keep the order')}</button><button class="danger">${es('Sí, eliminar','Yes, delete')}</button></footer></form></div>`}
  document.addEventListener('submit',event=>{let form=event.target;if(form.id!=='history-order-delete-form')return;event.preventDefault();event.stopImmediatePropagation();let order=activeOperation?.target,id=order?.id,result=runtime.dispatchAction({action:'delete-order',phase:'commit',targetId:id,resource:{type:'order',id},operationToken:activeOperation?.operationToken});if(result.ok){activeOperation=null;modal.innerHTML='';renderCurrentRoute();message(es('Orden de compra eliminada.','Purchase order deleted.'))}else message(ACL.t(lang(),'stale'))},true);
